         AND T1.RCPT_INST_NO = #{INST_NOS[0]}


         AND T1.RCPT_INST_NO IN

       #{item}




     /*종사자 selectTrprInfoList*/
     /*  목록은 권한적용을 하되 작성자 레벨까지는 하지 말고 소속 기관까지만 레벨로*/

/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리종료*/       


--20230629 이승재 - 증명서에서 조회시 사례담당자로 등록된 대상자만 출력 시작


         AND ((T2.CASE_MNG_NO, T2.CASE_MNG_ODRNO) IN (
             SELECT CASE_MNG_NO, CASE_MNG_ODRNO
                 FROM SEB150
                 WHERE CASE_MNG_NO = T2.CASE_MNG_NO
                     AND CASE_MNG_ODRNO = T2.CASE_MNG_ODRNO
                     AND CASE_PIC_NO = #{ENFSN_NO}
         ) OR (T1.RCPT_PIC_NO = #{ENFSN_NO}))


--20230629 이승재 - 증명서에서 조회시 사례담당자로 등록된 대상자 OR 발굴담당자로 등록된 대상자만 출력 종료

sql.if:
/* Default  */
          AND T1.UNT_TASKWK_SE_CD      = #{UNT_TASKWK_SE_CD}                     /* 단위업무구분(화면 좌측상단체크박스) */
          AND T1.CASE_MNG_SE_CD        IN ('01', '02','03','04')                /* 사례관리구분코드(01:사례대상자미신청, 02:사례대상자신청(대기상태), 03:사례대상자미선정, 04:사례대상자선정) */

/* 발굴등록 최초Load 시 */ 

        AND T1.UNT_TASKWK_SE_CD      = #{UNT_TASKWK_SE_CD}                   /* 단위업무구분(화면 좌측상단체크박스) */
        AND T1.CASE_MNG_SE_CD        IN ('01', '02','03','04')                /* 사례관리구분코드(01:사례대상자미신청, 02:사례대상자신청(대기상태), 03:사례대상자미선정, 04:사례대상자선정) */

/* 발굴등록 조회버튼 클릭 시 */ 

        AND T1.UNT_TASKWK_SE_CD IS NOT NULL                                  /* 단위업무구분(화면 좌측상단체크박스) */
        AND T1.CASE_MNG_SE_CD        IN ('01', '02','03','04')                /* 사례관리구분코드(01:사례대상자미신청, 02:사례대상자신청(대기상태), 03:사례대상자미선정, 04:사례대상자선정) */

mapper.select:
SELECT /* isry.itgcm.bizcmmns.cmmns.TrprInfoMapper.getTrprInfoList(대상자정보 목록건수) */ COUNT(*) FROM ( SELECT T.* FROM ( SELECT T1.* , T2.* , ( SELECT X.INST_NM FROM SAA000 X WHERE X.INST_NO = T1.RCPT_INST_NO ) AS RCPT_INST_NM /* 접수기관명 */ FROM SEA200 T1 ,SEB100 T2 WHERE 1=1 AND (T2.CASE_MNG_ODRNO = (SELECT MAX(CASE_MNG_ODRNO) FROM SEB100 WHERE CASE_MNG_NO=T2.CASE_MNG_NO) OR CASE_MNG_ODRNO IS NULL) AND T1.TRPR_INFO_NO = T2.TRPR_INFO_NO(+) AND T1.DEL_YN = 'N' /* 삭제여부*/ AND T1.FRST_REG_DT BETWEEN TO_DATE(NVL(#{REG_BGNG_YMD}, '00010101') || '000000', 'YYYYMMDDHH24MISS') /* 등록시작일자 */ AND TO_DATE(NVL(#{REG_END_YMD}, '99991231') || '235959', 'YYYYMMDDHH24MISS') /* 등록종료일자 */
) T WHERE 1 = 1
AND (T.RCPT_INST_NM NOT LIKE '%경찰서%' AND T.RCPT_INST_NM NOT LIKE '%경찰청%')
)

SELECT /* isry.itgcm.bizcmmns.cmmns.TrprInfoMapper.selectTrprInfoList(대상자정보 목록조회) */ T.* FROM ( SELECT #{TOT_CNT} AS TOT_CNT , ROWNUM AS SEQ , T1.* FROM ( SELECT T1.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호 */ ,T1.INDV_IDNTFC_NO AS INDV_IDNTFC_NO /* 개인식별번호 */ ,T2.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호(CS) */ ,(SELECT MAX(CASE_MNG_ODRNO) FROM SEB100 WHERE CASE_MNG_NO=T2.CASE_MNG_NO) AS CASE_MNG_ODRNO /* 사례관리차수 */ ,T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */ ,C##RG.DEC_B64(T1.TRPR_NM_ENCPT) AS TRPR_NM /* 대상자명암호화 */ ,T1.TRPR_BRTH_YMD AS TRPR_BRTH_YMD /* 대상자출생일자 */ , CASE WHEN T1.INDV_IDNTFC_NO IS NOT NULL THEN (SELECT C##RG.DEC_B64(RRNO_ENCPT) FROM SCA300 X WHERE X.INDV_IDNTFC_NO =T1.INDV_IDNTFC_NO) ELSE NULL END AS RRNO /* 주민등록번호암호화*/ ,T1.SXDC_SE_CD AS SXDC_SE_CD /* 성별구분코드 */ ,C##RG.DEC_B64(T1.MBL_TELNO_ENCPT) AS MBL_TELNO /* 휴대전화번호암호화 */ ,T1.TRPR_TELNO AS TRPR_TELNO /* 대상자전화번호 */ ,C##RG.DEC_B64(T1.EML_ADDR_ENCPT) AS EML_ADDR /* 이메일주소암호화 */ ,T1.SNS_SE_CD AS SNS_SE_CD /* SNS구분코드 */ ,C##RG.DEC_B64(T1.MSNGR_ID_ENCPT) AS MSNGR_ID /* 메신저아이디암호화 */ ,T1.ZIP AS ZIP /* 우편번호 */ ,T1.PST_ADDR AS PST_ADDR /* 우편주소 */ ,T1.DADDR AS DADDR /* 상세주소 */ ,T1.RCPT_PIC_NO AS RCPT_PIC_NO /* 접수담당자번호 */ , ( SELECT X.FLNM_ENCPT FROM SCA100 X WHERE X.ENFSN_NO = T1.RCPT_PIC_NO ) AS FLNM_ENCPT /* 접수담당자명 */ , T1.RCPT_INST_NO AS RCPT_INST_NO /* 접수기관번호 */ , ( SELECT X.INST_NM FROM SAA000 X WHERE X.INST_NO = T1.RCPT_INST_NO ) AS RCPT_INST_NM /* 접수기관명 */ , CASE WHEN T1.ZIP IS NULL THEN NULL ELSE '(' || T1.ZIP || ') ' || T1.PST_ADDR || ' ' || T1.DADDR END AS ADDR /* 주소*/ , T1.CASE_MNG_SE_CD AS CASE_MNG_SE_CD /* 사례관리구분코드 */ , T2.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드 */ , T1.MRG_YN AS MRG_YN /* 결혼여부 */ , T1.TRPR_USER_ID AS TRPR_USER_ID /* 대상자사용자아이디 */ , T1.GRADE_SE_CD AS GRADE_SE_CD /* 학년구분코드 */ , C##RG.DEC_B64(T1.PSPT_ENG_FLNM_ENCPT) AS PSPT_ENG_FLNM /* 여권영문성명암호화 */ , T1.TRPR_BCRN_TYPE_SE_CD AS TRPR_BCRN_TYPE_SE_CD /* 대상자배경유형구분코드 */ , T1.TRPR_BCRN_TYPE_RM_NM AS TRPR_BCRN_TYPE_RM_NM /* 대상자배경유형비고명 */ , T1.NLTY_NTN_SE_CD AS NLTY_NTN_SE_CD /* 국적국가구분코드 */ , T1.ENTCNY_YMD AS ENTCNY_YMD /* 입국일자 */ , T1.BRTH_NTN_SE_CD AS BRTH_NTN_SE_CD /* 출생국가구분코드 */ , T1.GROWTH_NTN_SE_CD AS GROWTH_NTN_SE_CD /* 성장국가구분코드 */ , T1.VISA_TYPE_SE_CD AS VISA_TYPE_SE_CD /* 비자유형구분코드 */ , T1.HANAWO_PENU_NO AS HANAWO_PENU_NO /* 하나원기수번호 */ , T1.RELGN_SE_CD AS RELGN_SE_CD /* 종교구분코드 */ , T1.QLFC_INFO_MNG_NO AS QLFC_INFO_MNG_NO /* 자격정보관리번호 */ , T1.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드 */ , T1.CASE_TRPR_SLCTN_YMD AS CASE_TRPR_SLCTN_YMD /* 사례대상자선정일자 */ , T1.CASE_TRPR_UNSL_CS_CN AS CASE_TRPR_UNSL_CS_CN /* 사례대상자미선정사유내용 */ , T1.PRTCR_NM_ENCPT AS PRTCR_NM_ENCPT /* 보호자명암호화 */ , T1.TRPR_REL_SE_CD AS TRPR_REL_SE_CD /* 대상자관계구분코드 */ , NVL(T1.LIVTGT_YN,'N') AS LIVTGT_YN /* 동거여부 */ , NVL(T1.PRTCR_AGRE_YN,'N') AS PRTCR_AGRE_YN /* 보호자동의여부 */ , NVL(T1.PRVC_PVSN_AGRE_YN,'N') AS PRVC_PVSN_AGRE_YN /* 개인정보제공동의여부 */ , NVL(T1.SRVC_CTRT_AGRE_YN,'N') AS SRVC_CTRT_AGRE_YN /* 서비스계약동의여부 */ , T1.TAG_NM AS TAG_NM /* 태그명 */ , T1.TAG_NO AS TAG_NO /* 태그번호 */ , T1.CASE_TRPR_NOAP_CS_SE_CD AS CASE_TRPR_NOAP_CS_SE_CD /* 사례대상자미신청사유구분코드 */ , T1.PRTCR_TELNO AS PRTCR_TELNO /* 보호자전화번호 */ , C##RG.DEC_B64(T1.PRTCR_MBL_TELNO_ENCPT) AS PRTCR_MBL_TELNO /* 보호자휴대전화번호암호화 */ , C##RG.DEC_B64(T1.PRTCR_EML_ADDR_ENCPT) AS PRTCR_EML_ADDR /* 보호자이메일주소암호화 */ , T1.PRTCR_ZIP AS PRTCR_ZIP /* 보호자우편번호 */ , T1.PRTCR_PST_ADDR AS PRTCR_PST_ADDR /* 보호자우편주소 */ , T1.PRTCR_DADDR AS PRTCR_DADDR /* 보호자상세주소 */ , T1.RESDN_SHAPE_SE_CD AS RESDN_SHAPE_SE_CD /* 거주형태구분코드 */ , T1.RESIDE_SHAPE_SE_CD AS RESIDE_SHAPE_SE_CD /* 주거형태구분코드 */ , T1.RESIDE_SHAPE_ETC_CN AS RESIDE_SHAPE_ETC_CN /* 주거형태기타내용 */ , T1.FAM_CHAR_SE_CD AS FAM_CHAR_SE_CD /* 가족특성구분코드 */ , T1.INDV_IDNTFC_INFO_UNIPT_CS_CN AS INDV_IDNTFC_INFO_UNIPT_CS_CN /* 개인식별정보미입력사유내용 */ , T1.INDV_IDNTFC_CRTR_YMD AS INDV_IDNTFC_CRTR_YMD /* 개인식별기준일자 */ , T1.PBLAST_SE_CD AS PBLAST_SE_CD /* 공적부조구분코드(사회보장구분코드) */ , T1.LINK_ADDTNG_DATAA_VALUE1 AS LINK_ADDTNG_DATAA_VALUE1 /* 연계추가데이터값1*/ , T1.LINK_ADDTNG_DATAA_VALUE2 AS LINK_ADDTNG_DATAA_VALUE2 /* 연계추가데이터값2*/ , T1.LINK_ADDTNG_DATAA_VALUE3 AS LINK_ADDTNG_DATAA_VALUE3 /* 연계추가데이터값3*/ , T1.LINK_ADDTNG_DATAA_VALUE4 AS LINK_ADDTNG_DATAA_VALUE4 /* 연계추가데이터값4*/ , T1.LINK_ADDTNG_DATAA_VALUE5 AS LINK_ADDTNG_DATAA_VALUE5 /* 연계추가데이터값5*/ , T1.LINK_ADDTNG_DATAA_VALUE6 AS LINK_ADDTNG_DATAA_VALUE6 /* 연계추가데이터값6*/ , T1.LINK_ADDTNG_DATAA_VALUE7 AS LINK_ADDTNG_DATAA_VALUE7 /* 연계추가데이터값7*/ , T1.LINK_ADDTNG_DATAA_VALUE8 AS LINK_ADDTNG_DATAA_VALUE8 /* 연계추가데이터값8*/ , T1.LINK_ADDTNG_DATAA_VALUE9 AS LINK_ADDTNG_DATAA_VALUE9 /* 연계추가데이터값9*/ , T1.LINK_ADDTNG_DATAA_VALUE10 AS LINK_ADDTNG_DATAA_VALUE10 /* 연계추가데이터값10*/ , T1.TRPR_PHOTO_ATFINO AS TRPR_PHOTO_ATFINO /* 대상자사진첨부파일번호*/ , T1.TRMN_CASE_MNG_NO AS TRMN_CASE_MNG_NO /* 종결사례관리번호*/ , T1.TRMN_CASE_MNG_ODRNO AS TRMN_CASE_MNG_ODRNO /* 종결사례관리차수*/ , T1.RCPT_RQST_COURS_SE_CD AS RCPT_RQST_COURS_SE_CD /* 접수의뢰경로구분코드*/ , T1.RCPT_RQST_COURS_ETC_CN AS RCPT_RQST_COURS_ETC_CN /* 접수의뢰경로기타내용*/ , (SELECT X.CMMNS_CD_VALUE_NM FROM SAC100 X WHERE X.CMMNS_CD_ID = 'RCPT_RQST_COURS_SE_CD' AND X.CMMNS_CD_VALUE = T1.RCPT_RQST_COURS_SE_CD) AS RCPT_RQST_COURS_SE_NM /* 접수의뢰경로구분명*/ , T1.FAM_SHAPE_SE_CD AS FAM_SHAPE_SE_CD /* 가족형태구분코드*/ , T1.FAM_SHAPE_ETC_CN AS FAM_SHAPE_ETC_CN /* 가족형태기타내용*/ , T1.FAM_CHAR_ETC_CN AS FAM_CHAR_ETC_CN /* 가족특성기타내용*/ , T1.PRVC_AGRE_YMD AS PRVC_AGRE_YMD /* 개인정보동의일자*/ , T1.TRPR_REL_ETC_CN AS TRPR_REL_ETC_CN /* 대상자관계기타내용*/ , T1.FAM_REL_SE_CD AS FAM_REL_SE_CD /* 가족관계구분코드*/ , T1.FAM_REL_SE_ETC_CN AS FAM_REL_SE_ETC_CN /* 가족관계구분기타내용*/ , T1.FAM_CHAR_SE_CD_NM AS FAM_CHAR_SE_CD_NM /* 가족특성구분코드명*/ , T1.ATFINO AS ATFINO /* 첨부파일번호*/ , T1.ORGNL_USER_ID AS ORGNL_USER_ID /* 원본사용자아이디 */ , T1.ORGNL_DSCSN_APLY_CASE_NO AS ORGNL_DSCSN_APLY_CASE_NO /* 원본상담신청사례번호 */ , T1.ORGNL_REQSTD_MNG_NO AS ORGNL_REQSTD_MNG_NO /* 원본신청서관리번호 */ , T1.ORGNL_DSCSN_SN AS ORGNL_DSCSN_SN /* 원본상담일련번호 */ , T1.FRST_RGTR_ID AS FRST_RGTR_ID /* 최초등록자아이디 */ , T1.FRST_REG_DT AS FRST_REG_DT /* 최초등록일시 */ , T1.LAST_MDFR_ID AS LAST_MDFR_ID /* 최종수정자아이디 */ , T1.LAST_MDFCN_DT AS LAST_MDFCN_DT /* 최종수정일시 */ FROM SEA200 T1 ,SEB100 T2 WHERE 1=1 AND (T2.CASE_MNG_ODRNO = (SELECT MAX(CASE_MNG_ODRNO) FROM SEB100 WHERE CASE_MNG_NO=T2.CASE_MNG_NO) OR CASE_MNG_ODRNO IS NULL) AND T1.TRPR_INFO_NO = T2.TRPR_INFO_NO(+) AND T1.DEL_YN = 'N' /* 삭제여부*/ AND T1.FRST_REG_DT BETWEEN TO_DATE(NVL(#{REG_BGNG_YMD}, '00010101') || '000000', 'YYYYMMDDHH24MISS') /* 등록시작일자 */ AND TO_DATE(NVL(#{REG_END_YMD}, '99991231') || '235959', 'YYYYMMDDHH24MISS') /* 등록종료일자 */
ORDER BY T1.FRST_REG_DT DESC ) T1 WHERE 1 = 1
AND (T1.RCPT_INST_NM NOT LIKE '%경찰서%' AND T1.RCPT_INST_NM NOT LIKE '%경찰청%')
) T WHERE 1 = 1
AND T.SEQ >= #{START_IDX} AND T.SEQ <= #{LAST_IDX}

SELECT S1.* FROM ( SELECT /*+ INDEX_DESC(T1 SEA200_PK)*/ T1.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호*/ , T1.INDV_IDNTFC_NO AS INDV_IDNTFC_NO /* 개인식별번호*/ , CASE WHEN T1.INDV_IDNTFC_NO IS NOT NULL THEN (SELECT C##RG.DEC_B64(RRNO_ENCPT) FROM SCA300 X WHERE X.INDV_IDNTFC_NO =T1.INDV_IDNTFC_NO) ELSE NULL END AS RRNO /* 주민등록번호암호화*/ , T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드*/ , C##RG.DEC_B64(T1.TRPR_NM_ENCPT) AS TRPR_NM /* 대상자명암호화*/ , T1.TRPR_BRTH_YMD AS TRPR_BRTH_YMD /* 대상자출생일자*/ , T1.SXDC_SE_CD AS SXDC_SE_CD /* 성별구분코드*/ , T1.MRG_YN AS MRG_YN /* 결혼여부*/ , T1.TRPR_USER_ID AS TRPR_USER_ID /* 대상자사용자아이디*/ , T1.TRPR_TELNO AS TRPR_TELNO /* 대상자전화번호*/ , C##RG.DEC_B64(T1.MBL_TELNO_ENCPT) AS MBL_TELNO /* 휴대전화번호암호화*/ , C##RG.DEC_B64(T1.EML_ADDR_ENCPT) AS EML_ADDR /* 이메일주소암호화*/ , T1.SNS_SE_CD AS SNS_SE_CD /* SNS구분코드*/ , ( SELECT X.CMMNS_CD_VALUE_NM FROM SAC100 X WHERE X.CMMNS_CD_ID = 'SNS_SE_CD' AND X.CMMNS_CD_VALUE = T1.SNS_SE_CD) AS SNS_SE_NM /* SNS구분명*/ , C##RG.DEC_B64(T1.MSNGR_ID_ENCPT) AS MSNGR_ID /* 메신저아이디암호화*/ , T1.ZIP AS ZIP /* 우편번호*/ , T1.PST_ADDR AS PST_ADDR /* 우편주소*/ , T1.DADDR AS DADDR /* 상세주소*/ , T1.ACBG_SE_CD AS ACBG_SE_CD /* 학력구분코드*/ , T1.GRDTN_STTS_SE_CD AS GRDTN_STTS_SE_CD /* 졸업상태구분코드*/ , T1.GRADE_SE_CD AS GRADE_SE_CD /* 학년구분코드*/ , C##RG.DEC_B64(T1.PSPT_ENG_FLNM_ENCPT) AS PSPT_ENG_FLNM /* 여권영문성명암호화*/ , T1.TRPR_BCRN_TYPE_SE_CD AS TRPR_BCRN_TYPE_SE_CD /* 대상자배경유형구분코드*/ , T1.TRPR_BCRN_TYPE_RM_NM AS TRPR_BCRN_TYPE_RM_NM /* 대상자배경유형비고명*/ , T1.NLTY_NTN_SE_CD AS NLTY_NTN_SE_CD /* 국적국가구분코드*/ , T1.ENTCNY_YMD AS ENTCNY_YMD /* 입국일자*/ , T1.BRTH_NTN_SE_CD AS BRTH_NTN_SE_CD /* 출생국가구분코드*/ , T1.GROWTH_NTN_SE_CD AS GROWTH_NTN_SE_CD /* 성장국가구분코드*/ , T1.VISA_TYPE_SE_CD AS VISA_TYPE_SE_CD /* 비자유형구분코드*/ , T1.HANAWO_PENU_NO AS HANAWO_PENU_NO /* 하나원기수번호*/ , T1.RELGN_SE_CD AS RELGN_SE_CD /* 종교구분코드*/ , T1.QLFC_INFO_MNG_NO AS QLFC_INFO_MNG_NO /* 자격정보관리번호*/ , T1.RCPT_PIC_NO AS RCPT_PIC_NO /* 접수담당자번호*/ , (SELECT C##RG.DEC_B64(X.FLNM_ENCPT) FROM SCA100 X WHERE X.ENFSN_NO = T1.RCPT_PIC_NO) AS FLNM/* 접수담당자명*/ , T1.RCPT_INST_NO AS RCPT_INST_NO /* 접수기관번호*/ , (SELECT X.INST_NM FROM SAA000 X WHERE X.INST_NO = T1.RCPT_INST_NO ) AS INST_NM /* 접수기관명*/ , T1.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드*/ , T1.CASE_MNG_SE_CD AS CASE_MNG_SE_CD /* 사례관리구분코드*/ , T1.CASE_TRPR_SLCTN_YMD AS CASE_TRPR_SLCTN_YMD /* 사례대상자선정일자*/ , T1.CASE_TRPR_UNSL_CS_CN AS CASE_TRPR_UNSL_CS_CN /* 사례대상자미선정사유내용*/ , T1.TRPR_REL_SE_CD AS TRPR_REL_SE_CD /* 대상자관계구분코드*/ , T1.LIVTGT_YN AS LIVTGT_YN /* 동거여부*/ , T1.PRTCR_AGRE_YN AS PRTCR_AGRE_YN /* 보호자동의여부*/ , T1.PRVC_PVSN_AGRE_YN AS PRVC_PVSN_AGRE_YN /* 개인정보제공동의여부*/ , T1.SRVC_CTRT_AGRE_YN AS SRVC_CTRT_AGRE_YN /* 서비스계약동의여부*/ , T1.TAG_NM AS TAG_NM /* 태그명*/ , T1.TAG_NO AS TAG_NO /* 태그번호*/ , T1.CASE_TRPR_NOAP_CS_SE_CD AS CASE_TRPR_NOAP_CS_SE_CD /* 사례대상자미신청사유구분코드*/ , C##RG.DEC_B64(T1.PRTCR_NM_ENCPT) AS PRTCR_NM /* 보호자명암호화*/ , T1.PRTCR_BRTH_YMD AS PRTCR_BRTH_YMD /* 보호자출생일자*/ , T1.PRTCR_TELNO AS PRTCR_TELNO /* 보호자전화번호*/ , C##RG.DEC_B64(T1.PRTCR_MBL_TELNO_ENCPT) AS PRTCR_MBL_TELNO /* 보호자휴대전화번호암호화*/ , C##RG.DEC_B64(T1.PRTCR_EML_ADDR_ENCPT) AS PRTCR_EML_ADDR /* 보호자이메일주소암호화*/ , T1.PRTCR_ZIP AS PRTCR_ZIP /* 보호자우편번호*/ , T1.PRTCR_PST_ADDR AS PRTCR_PST_ADDR /* 보호자우편주소*/ , T1.PRTCR_DADDR AS PRTCR_DADDR /* 보호자상세주소*/ , T1.RESDN_SHAPE_SE_CD AS RESDN_SHAPE_SE_CD /* 거주형태구분코드*/ , T1.RESIDE_SHAPE_SE_CD AS RESIDE_SHAPE_SE_CD /* 주거형태구분코드*/ , T1.RESIDE_SHAPE_ETC_CN AS RESIDE_SHAPE_ETC_CN /* 주거형태기타내용*/ , T1.FAM_CHAR_SE_CD AS FAM_CHAR_SE_CD /* 가족특성구분코드*/ , T1.INDV_IDNTFC_INFO_UNIPT_CS_CN AS INDV_IDNTFC_INFO_UNIPT_CS_CN /* 개인식별정보미입력사유내용*/ , T1.INDV_IDNTFC_CRTR_YMD AS INDV_IDNTFC_CRTR_YMD /* 개인식별기준일자*/ , T1.PBLAST_SE_CD AS PBLAST_SE_CD /* 공적부조구분코드(사회보장구분코드)*/ , T1.LINK_ADDTNG_DATAA_VALUE1 AS LINK_ADDTNG_DATAA_VALUE1 /* 연계추가데이터값1*/ , T1.LINK_ADDTNG_DATAA_VALUE2 AS LINK_ADDTNG_DATAA_VALUE2 /* 연계추가데이터값2*/ , T1.LINK_ADDTNG_DATAA_VALUE3 AS LINK_ADDTNG_DATAA_VALUE3 /* 연계추가데이터값3*/ , T1.LINK_ADDTNG_DATAA_VALUE4 AS LINK_ADDTNG_DATAA_VALUE4 /* 연계추가데이터값4*/ , T1.LINK_ADDTNG_DATAA_VALUE5 AS LINK_ADDTNG_DATAA_VALUE5 /* 연계추가데이터값5*/ , T1.LINK_ADDTNG_DATAA_VALUE6 AS LINK_ADDTNG_DATAA_VALUE6 /* 연계추가데이터값6*/ , T1.LINK_ADDTNG_DATAA_VALUE7 AS LINK_ADDTNG_DATAA_VALUE7 /* 연계추가데이터값7*/ , T1.LINK_ADDTNG_DATAA_VALUE8 AS LINK_ADDTNG_DATAA_VALUE8 /* 연계추가데이터값8*/ , T1.LINK_ADDTNG_DATAA_VALUE9 AS LINK_ADDTNG_DATAA_VALUE9 /* 연계추가데이터값9*/ , T1.LINK_ADDTNG_DATAA_VALUE10 AS LINK_ADDTNG_DATAA_VALUE10 /* 연계추가데이터값10*/ , T1.TRPR_PHOTO_ATFINO AS TRPR_PHOTO_ATFINO /* 대상자사진첨부파일번호*/ , T1.TRMN_CASE_MNG_NO AS TRMN_CASE_MNG_NO /* 종결사례관리번호*/ , T1.TRMN_CASE_MNG_ODRNO AS TRMN_CASE_MNG_ODRNO /* 종결사례관리차수*/ , T1.RCPT_RQST_COURS_SE_CD AS RCPT_RQST_COURS_SE_CD /* 접수의뢰경로구분코드*/ , T1.RCPT_RQST_COURS_ETC_CN AS RCPT_RQST_COURS_ETC_CN /* 접수의뢰경로기타내용*/ , T1.FAM_SHAPE_SE_CD AS FAM_SHAPE_SE_CD /* 가족형태구분코드*/ , T1.FAM_SHAPE_ETC_CN AS FAM_SHAPE_ETC_CN /* 가족형태기타내용*/ , T1.FAM_CHAR_ETC_CN AS FAM_CHAR_ETC_CN /* 가족특성기타내용*/ , T1.PRVC_AGRE_YMD AS PRVC_AGRE_YMD /* 개인정보동의일자*/ , T1.TRPR_REL_ETC_CN AS TRPR_REL_ETC_CN /* 대상자관계기타내용*/ , T1.FAM_REL_SE_CD AS FAM_REL_SE_CD /* 가족관계구분코드*/ , T1.FAM_REL_SE_ETC_CN AS FAM_REL_SE_ETC_CN /* 가족관계구분기타내용*/ , T1.FAM_CHAR_SE_CD_NM AS FAM_CHAR_SE_CD_NM /* 가족특성구분코드명*/ , T1.ATFINO AS ATFINO /* 첨부파일번호*/ , T1.ORGNL_USER_ID AS ORGNL_USER_ID /* 원본사용자아이디*/ , T1.ORGNL_DSCSN_APLY_CASE_NO AS ORGNL_DSCSN_APLY_CASE_NO /* 원본상담신청사례번호*/ , T1.ORGNL_REQSTD_MNG_NO AS ORGNL_REQSTD_MNG_NO /* 원본신청서관리번호*/ , T1.ORGNL_DSCSN_SN AS ORGNL_DSCSN_SN /* 원본상담일련번호*/ , T1.FRST_RGTR_ID AS FRST_RGTR_ID /* 최초등록자아이디*/ , T1.FRST_REG_DT AS FRST_REG_DT /* 최초등록일시*/ , T1.LAST_MDFR_ID AS LAST_MDFR_ID /* 최종수정자아이디*/ , T1.LAST_MDFCN_DT AS LAST_MDFCN_DT /* 최종수정일시*/ , T2.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드*/ , T2.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호*/ , (SELECT CASE WHEN COUNT(1) > 0 THEN 'Y' ELSE 'N' END FROM SEA240 WHERE TRPR_INFO_NO = T1.TRPR_INFO_NO) AS SCHULW_DSCNTC_YN /* 학업중단여부*/ , ROWNUM AS SEQ FROM SEA200 T1, ( SELECT TT2.* FROM ( SELECT TTT2.CASE_MNG_NO , TTT2.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD , TTT2.TRPR_INFO_NO AS TRPR_INFO_NO , ROW_NUMBER() OVER (PARTITION BY TTT2.TRPR_INFO_NO ORDER BY TTT2.FRST_REG_DT DESC) AS RN FROM SEB100 TTT2 ) TT2 WHERE TT2.RN = 1 ) T2 WHERE 1=1
) S1 WHERE 1 = 1
AND S1.SEQ >= #{START_IDX} AND S1.SEQ <= #{LAST_IDX}

mapper.sql:
 AND T1.TRPR_INFO_NO = T2.TRPR_INFO_NO(+)
 AND T1.RCPT_INST_NO IN (SELECT S1.INST_NO FROM SAA000 S1 WHERE S1.INST_NM NOT LIKE '%경찰서' UNION SELECT S1.INST_NO FROM SAA000 S1 WHERE S1.INST_NM NOT LIKE '%경찰청')
 AND T1.DEL_YN               = 'N'                                    /* 삭제여부*/
 AND T1.FRST_REG_DT BETWEEN TO_DATE(#{REG_BGNG_YMD} || '000000', 'YYYYMMDDHH24MISS') AND TO_DATE(#{REG_END_YMD} || '235959', 'YYYYMMDDHH24MISS')  
 AND (T1.CASE_MNG_SE_CD = '02' OR ( T1.CASE_MNG_SE_CD = '04' AND T2.CASE_PRGRS_STTS_SE_CD IN ('04', '08')))     /* 사례관리구분코드(사례신청(대기상태) : 02, 사례대상자선정 : 04)*/
 AND T1.UNT_TASKWK_SE_CD     = #{UNT_TASKWK_SE_CD}               /* 단위업무구분(화면 좌측상단체크박스)*/
 /* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리시작*/                               


         AND T1.RCPT_INST_NO = #{INST_NOS[0]}


         AND T1.RCPT_INST_NO IN

       #{item}




     /*종사자 selectTrprInfoInqPagingList*/
     /*  목록은 권한적용을 하되 작성자 레벨까지는 하지 말고 소속 기관까지만 레벨로*/

/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리종료*/               


     AND T1.TRPR_NM_ENCPT        = (C##RG.ENC_B64(#{TRPR_NM}))                    /* 대상자명*/           


     AND T1.TRPR_TELNO           = #{TRPR_TELNO}                      /* 전화번호*/           


     AND T1.MBL_TELNO_ENCPT      = (C##RG.ENC_B64(#{MBL_TELNO}))                 /* 휴대전화번호*/           


     AND T1.EML_ADDR_ENCPT       = (C##RG.ENC_B64(#{EML_ADDR}))                  /* 이메일주소*/           


     AND T1.SNS_SE_CD            = #{SNS_SE_CD}                       /* SNS구분코드*/ 
     AND T1.MSNGR_ID_ENCPT       = (C##RG.ENC_B64(#{MSNGR_ID}))                   /* 메신저아이디*/           


     AND T1.TRPR_BRTH_YMD       = #{TRPR_BRTH_YMD}                      /* 생년월일*/
